#!/usr/bin/env bash
# PreToolUse hook: block edits to files that are auto-generated by the
# monorepo's build chain. Editing these by hand silently breaks the next
# build/install cycle. The user can still bypass by editing the source
# and re-running the appropriate generator.
#
# Exit 2 = block the tool call.
set -e

input=$(cat)
file=$(echo "$input" | jq -r '.tool_input.file_path // empty')
case "$file" in
  *.tgz)
    echo "BLOCKED: $file is a packed tarball produced by 'npm pack'. Edit paperboy-converter/src/ and re-run 'npm run sync:all' instead." >&2
    exit 2
    ;;
  */package-lock.json)
    # Only block at sub-package level; the root one is the workspace lock
    # and is regenerated by 'npm install'. Sub-locks should not exist
    # under workspaces.
    case "$file" in
      */paperboy/package-lock.json) exit 0 ;;
      */paperboy-site/package-lock.json) exit 0 ;;
      *)
        echo "BLOCKED: $file shouldn't exist under npm workspaces. Run 'npm install' at the monorepo root instead." >&2
        exit 2
        ;;
    esac
    ;;
esac
